package com.nigson.commerce.pricing;
import java.util.*;import jakarta.servlet.http.HttpServletRequest;import org.springframework.web.bind.annotation.*;import org.springframework.http.ResponseEntity;import org.springframework.security.core.context.SecurityContextHolder;import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty;import com.nigson.shared.security.ActorAssertion;import com.nigson.shared.problem.*;import com.nigson.shared.observability.WireContext;import tools.jackson.databind.JsonNode;
@RestController @ConditionalOnProperty(name="NIGSON_SECURITY_ENABLED",havingValue="true")
public final class ProductPriceController{
 private final ProductPrices prices;public ProductPriceController(ProductPrices prices){this.prices=prices;}
 private ActorAssertion.Actor actor(HttpServletRequest request,boolean read)throws java.io.IOException{if(!request.getParameterMap().isEmpty()||read&&request.getInputStream().read()!=-1)throw ApiValues.invalid();var auth=SecurityContextHolder.getContext().getAuthentication();if(auth==null||!auth.isAuthenticated())throw new Problem.Failure(ProblemCode.AUTH_REQUIRED);if(!(auth.getPrincipal() instanceof ActorAssertion.Actor actor))throw new Problem.Failure(ProblemCode.ACCESS_DENIED);return actor;}
 @GetMapping(value="/api/v1/staff/skus/{id}/commercial-prices",produces="application/json")public ResponseEntity<ProductPrices.View> get(HttpServletRequest request,@PathVariable String id)throws java.io.IOException{return ResponseEntity.ok().header("Cache-Control","no-store").body(prices.get(actor(request,true),ApiValues.uuid(id)));}
 @PutMapping(value="/api/v1/staff/skus/{id}/commercial-prices",consumes="application/json",produces="application/json")public ResponseEntity<ProductPrices.View> save(HttpServletRequest request,@PathVariable String id,@RequestBody JsonNode body)throws java.io.IOException{var keys=Collections.list(request.getHeaders("Idempotency-Key"));if(keys.size()!=1)throw ApiValues.invalid();var wire=WireContext.current();return ResponseEntity.ok().header("Cache-Control","no-store").body(prices.save(actor(request,false),ApiValues.uuid(id),ProductPrices.parse(body),keys.getFirst(),wire==null?WireContext.correlation(null):wire.correlationId));}
}
